    "source": "def matrix_chain_order(dims: list[int]) -> tuple[int, list[list[int]]]:\n    \"\"\"Matrix-chain order DP — complete Python reference. Returns (cost, split).\"\"\"\n    n = len(dims) - 1\n    dp: list[list[float]] = [[0] * n for _ in range(n)]\n    split = [[0] * n for _ in range(n)]\n    for length in range(2, n + 1):\n        for i in range(n - length + 1):\n            j = i + length - 1\n            dp[i][j] = float(\"inf\")\n            for k in range(i, j):\n                cost = dp[i][k] + dp[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1]\n                if cost < dp[i][j]:\n                    dp[i][j] = cost\n                    split[i][j] = k\n    return int(dp[0][n - 1]), split\n",
