    "source": "/// Matrix-chain order DP — complete Rust reference. Returns (cost, split).\npub fn matrix_chain_order(dims: &[i64]) -> (i64, Vec<Vec<usize>>) {\n    let n = dims.len() - 1;\n    let mut dp = vec![vec![0i64; n]; n];\n    let mut split = vec![vec![0usize; n]; n];\n    for len in 2..=n {\n        for i in 0..=n - len {\n            let j = i + len - 1;\n            dp[i][j] = i64::MAX;\n            for k in i..j {\n                let cost = dp[i][k] + dp[k + 1][j] + dims[i] * dims[k + 1] * dims[j + 1];\n                if cost < dp[i][j] {\n                    dp[i][j] = cost;\n                    split[i][j] = k;\n                }\n            }\n        }\n    }\n    (dp[0][n - 1], split)\n}\n",
